126: export async function runScan(): Promise<void> {
127:   const btn = document.getElementById('btn-scan') as HTMLButtonElement | null;
128:   const progressBar = document.getElementById('scan-progress') as HTMLElement | null;
129:   const progressFill = document.getElementById('scan-progress-fill') as HTMLElement | null;
130:   const progressText = document.getElementById('scan-progress-text') as HTMLElement | null;
131: 
132:   if (btn) btn.disabled = true;
133:   if (btn) btn.classList.add('scanning');
134:   if (progressBar) progressBar.classList.remove('hidden');
135:   if (progressFill) progressFill.style.width = '0%';
136:   if (progressText) progressText.textContent = '🔍 Préparation…';
137:   setStatus('Scan en cours…');
138: 
139:   const pollTimer = setInterval(async () => {
140:     try {
141:       const p = await api<{ running: boolean; total: number; current: number; phase?: string }>('/scan-progress');
142:       if (!p.running) {
143:         clearInterval(pollTimer);
144:         return;
145:       }
146:       const pct = p.total > 0 ? Math.round((p.current / p.total) * 100) : 0;
147:       if (progressFill) progressFill.style.width = `${Math.min(pct, 100)}%`;
148:       if (progressText) progressText.textContent = `${p.phase || '…'} : ${p.current} / ${p.total} (${pct}%)`;
149:       setStatus(`🔍 Scan ${p.phase ? p.phase.toLowerCase() : '…'} — ${p.current}/${p.total}`);
150:     } catch (_) {
