166:     state.sourceIndex = (data.source_index || {}) as typeof state.sourceIndex;
167:     state.journal = await api<typeof state.journal>('/journal');
168:     refreshDupMatches();
169:     // EventEmitter auto-renders panels via subscriptions
170:     // Double-RAF restores focus after EventEmitter's deferred render
171:     requestAnimationFrame(() => requestAnimationFrame(revalidateFocus));
172:   } catch (err) {
173:     scanFailed = true;
174:     showError(`Scan échoué : ${err instanceof Error ? err.message : String(err)}`);
175:   } finally {
176:     clearInterval(pollTimer);
177:     if (btn) {
178:       btn.disabled = false;
179:       btn.classList.remove('scanning');
180:     }
181:     if (progressBar) progressBar.classList.add('hidden');
182:     if (progressFill) progressFill.style.width = '0%';
183:     if (!scanFailed) {
184:       const totalFiles =
185:         Object.values(state.sourceFiles).reduce((s, f) => s + Object.keys(f).length, 0) +
186:         Object.values(state.eparsFiles).reduce((s, f) => s + Object.keys(f).length, 0);
187:       setStatus(`Scan terminé — ${fmtCount(totalFiles)} fichiers`);
188:     }
189:   }
190: }
