223: /** Racines Source Data connues du client : les racines scannées + celle de la
224:  *  config active (une racine jamais scannée déclare quand même ses dossiers). */
225: function sourceRoots(): string[] {
226:   const roots = Object.keys(state.sourceFiles);
227:   const cfg = configData.configs[configData.active];
228:   if (cfg?.source_data && !roots.includes(cfg.source_data)) roots.push(cfg.source_data);
