232: /** Style déclaré par un dossier de destination, vu depuis une racine Source
233:  *  Data : **premier segment** du chemin relatif. Miroir client de
234:  *  `_style_of_dest_dir` (app.py) — même grammaire `parseFolderName`, tenue
235:  *  honnête par une table de noms testée des deux côtés. null si la destination
236:  *  n'est pas sous une racine connue, ou si le segment ne déclare rien
237:  *  (`_trash`, `2008_08`, dossier capitalisé). */
238: export function styleOfDestDir(destDir: string): string | null {
239:   const root = sourceRoots().find(dir => destDir === dir || destDir.startsWith(dir.endsWith('/') ? dir : `${dir}/`));
240:   if (!root) return null;
241:   const rel = destDir === root ? '' : destDir.substring(root.length).replace(/^\/+/, '');
242:   const seg = rel.split('/')[0];
243:   return seg ? (parseFolderName(seg)?.style ?? null) : null;
244: }
245: 
246: /** Phrase de consentement de la modale F5 : la copie écrit le style déclaré par
247:  *  le dossier cible (EPIC-043). '' si la destination ne déclare rien — le
248:  *  comportement d'avant, sans mention. */
249: export function styleConsentLine(destDir: string): string {
250:   const style = styleOfDestDir(destDir);
251:   return style
252:     ? `Le style « ${style} » du dossier cible sera écrit dans le tag genre, sur l'épars et sur la copie (l'année n'est pas touchée).`
253:     : '';
254: }
255: 
256: /** Consentement CONDENSÉ pour la modale structurée (revue du 2026-09-23) : une
257:  *  ligne, sans wrap — le détail complet reste dans styleConsentLine (tests,
258:  *  journal) et le texte intégral est au tooltip de la ligne discrète. null si
259:  *  la destination ne déclare rien. */
260: export function styleConsentShort(destDir: string): string | null {
261:   const style = styleOfDestDir(destDir);
262:   return style ? `Style « ${style} » écrit sur l'épars et la copie · année intacte` : null;
263: }
264: 
265: /** Note de statut de l'écriture de style ('' si rien à signaler). Un échec est
266:  *  RAPPORTÉ, jamais bloquant : la copie a réussi, le tag est un effet de bord. */
267: export function styleNoteOf(res: CopyResponse): string {
268:   if (!res.style) return res.style_error ? ` · style non écrit : ${res.style_error}` : '';
269:   if (res.style_error) return ` · style « ${res.style} » non écrit : ${res.style_error}`;
270:   const writes = res.style_writes ?? [];
271:   const ko = writes.filter(w => !w.ok);
272:   if (ko.length) {
273:     return ` · style « ${res.style} » non écrit sur ${ko.map(w => w.role).join(' + ')} : ${ko[0].error ?? 'échec'}`;
274:   }
275:   const changed = writes.filter(w => w.changed).map(w => w.role);
276:   return changed.length
277:     ? ` · style « ${res.style} » écrit (${changed.join(' + ')})`
278:     : ` · style « ${res.style} » déjà à jour`;
279: }
280: 
281: /** Répercute l'écriture de style sur l'état local : genre de l'épars (seulement
282:  *  s'il a été écrit) et cellule *Style* de la ligne (le chip « écrit ✓ »
283:  *  compare `entry.genre` au style choisi — sans ce patch il mentirait). */
284: function applyCopyStyle(fullSrc: string, eparDir: string, filename: string, res: CopyResponse): void {
285:   if (!res.style) return;
286:   const epars = (res.style_writes ?? []).find(w => w.role === 'epars');
287:   const entry = state.eparsFiles[eparDir]?.[filename];
288:   if (entry && epars?.ok) entry.genre = epars.style ?? res.style ?? null;
289:   refreshStyleCell(fullSrc); // EPIC-051 (D4) : le chip neutre suit `entry.genre` mis à jour
290: }
291: 
292: /** Copie `files` (épars) vers `destDir`, patch l'index + le DOM, recharge le
293:  *  journal, vide la sélection et révèle le dossier destination. Renvoie les
294:  *  fullpaths épars effectivement copiés et la note de style éventuelle
295:  *  (EPIC-043). Extrait du handler batch de F5 (EPIC-035) pour être enchaîné par
296:  *  dossier cible depuis l'aperçu de rangement — corps iso-comportement, aucune
297:  *  confirmation ici (l'appelant l'a déjà obtenue). */
298: export async function copyFilesTo(
