610: /** Applique le plan d'un groupe : gagnant épars → copié vers le dossier du
611:  *  meilleur rangé, PUIS tous les rangés perdants → _trash/<date>. Jamais
612:  *  d'effacement : si une copie échoue, aucun move n'a lieu (garde globale).
613:  *  Les épars perdants restent en place (décision utilisateur). overridePath
614:  *  désigne un autre survivant choisi par l'utilisateur. */
615: export async function applyGroupPlan(group: VersionGroup, overridePath: string | null): Promise<void> {
616:   let finalWinner = group.winner;
617:   if (overridePath) {
618:     const alt = group.members.find(m => m.fullPath === overridePath);
619:     if (alt) finalWinner = alt;
620:   }
621:   // EPIC-032 : seuls les rangés de MÊME ENREGISTREMENT (durée ±2 s du gagnant
622:   // désigné) vont au trash — les autres versions du morceau (mix, album,
623:   // radio…) sont hors de portée de l'arbitrage, même en override.
624:   const losers = group.members.filter(
625:     m => m.fullPath !== finalWinner.fullPath && m.side === 'source' && durationCompatible(m, finalWinner),
626:   );
627:   if (losers.length === 0) {
628:     setStatus('Rien à déplacer : le gagnant choisi est déjà le seul exemplaire rangé.');
629:     return;
630:   }
631:   const sourceRoot = Object.keys(state.sourceFiles).find(d => losers[0].fullPath.startsWith(`${d}/`));
632:   if (!sourceRoot) {
633:     showError('Dossier source introuvable pour le plan de groupe.');
634:     return;
635:   }
636:   const trashDir = `${sourceRoot}/_trash/${new Date().toISOString().slice(0, 10)}`;
637: 
638:   state.replaceBusy = true;
639:   try {
640:     // 1. Gagnant épars → copier vers la cible (dossier du meilleur rangé)
641:     if (finalWinner.side === 'epars') {
642:       await api('/copy', {
643:         method: 'POST',
644:         body: JSON.stringify({
645:           source_path: finalWinner.fullPath,
646:           dest_dir: group.copyTargetDir ?? sourceRoot,
647:           filename: finalWinner.filename,
648:         }),
649:       });
650:     }
651:     // 2. Rangés perdants → trash (collisions suffixées côté serveur)
652:     for (const loser of losers) {
653:       await api('/move', {
654:         method: 'POST',
655:         body: JSON.stringify({ source_path: loser.fullPath, dest_dir: trashDir }),
656:       });
657:     }
658:     // 3. State : retirer les perdants de sourceFiles
659:     for (const loser of losers) {
660:       const root = Object.keys(state.sourceFiles).find(d => loser.fullPath.startsWith(`${d}/`));
661:       if (root) delete state.sourceFiles[root][loser.filename];
662:     }
663:     state.sourceFiles = { ...state.sourceFiles }; // EventEmitter → re-render
664:     refreshDupMatches();
665:     setStatus(`✓ ${finalWinner.filename} conservé — ${losers.length} exemplaire(s) → _trash`);
666:   } catch (err) {
667:     showError(`Échec du plan de groupe : ${err instanceof Error ? err.message : String(err)}`);
668:   } finally {
669:     state.replaceBusy = false;
670:     requestAnimationFrame(() => requestAnimationFrame(revalidateFocus));
671:   }
672: }
