97: /** Distance de Levenshtein (DP compacte, O(min(m,n)) mémoire). */
98: function levenshtein(a: string, b: string): number {
99:   if (a === b) return 0;
100:   if (a.length === 0) return b.length;
101:   if (b.length === 0) return a.length;
102:   let prev = new Array<number>(b.length + 1);
103:   let curr = new Array<number>(b.length + 1);
104:   for (let j = 0; j <= b.length; j++) prev[j] = j;
105:   for (let i = 1; i <= a.length; i++) {
106:     curr[0] = i;
107:     for (let j = 1; j <= b.length; j++) {
108:       const cost = a[i - 1] === b[j - 1] ? 0 : 1;
109:       curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
110:     }
111:     [prev, curr] = [curr, prev];
112:   }
113:   return prev[b.length];
114: }
115: 
116: /** Ratio de Levenshtein (0..1), 1 = identique. */
117: export function levenshteinRatio(a: string, b: string): number {
118:   if (a === b) return 1;
119:   const maxLen = Math.max(a.length, b.length);
120:   if (maxLen === 0) return 1;
121:   return 1 - levenshtein(a, b) / maxLen;
122: }
