124: /** Similarité token-set : tokens communs / tokens totaux (ordre indifférent) —
125:  *  gère « Artiste - Titre » vs « Titre - Artiste ». */
126: export function tokenSetRatio(a: string, b: string): number {
127:   const ta = new Set(a.split(' ').filter(Boolean));
128:   const tb = new Set(b.split(' ').filter(Boolean));
129:   if (ta.size === 0 && tb.size === 0) return 1;
130:   let common = 0;
131:   for (const t of ta) if (tb.has(t)) common++;
132:   const total = ta.size + tb.size - common;
133:   return total === 0 ? 0 : common / total;
134: }
