102: export function buildTaxonomy(sourceFiles: Record<string, FileIndex>, extraDirs: Iterable<string>): Taxonomy | null {
103:   const root = Object.keys(sourceFiles)[0];
104:   if (!root) return null;
105:   const files = sourceFiles[root];
106:   if (!files || Object.keys(files).length === 0) return null;
