66: /** Normalise un segment pour lookup (minuscule, accents retirés, trim). */
67: function norm(s: string): string {
68:   return s
69:     .normalize('NFD')
70:     .replace(/[\u0300-\u036f]/g, '')
71:     .toLowerCase()
72:     .trim();
