75: /** Extrait les segments d'un chemin relatif épars, du plus profond au plus
76:  *  superficiel. `_techno/acid techno/track.mp3` → ['acid techno', '_techno'].
77:  *  Le premier segment (commençant par `_`) est un dossier de regroupement :
78:  *  on le normalise sans le `_` leading pour le lookup. */ export function pathSegments(relPath: string): string[] {
79:   const parts = relPath.split('/').filter(Boolean);
80:   // Un seul segment = fichier à la racine → aucun dossier
81:   if (parts.length <= 1) return [];
82:   // Retirer le nom de fichier (dernier segment)
83:   parts.pop();
84:   // Du plus profond au plus superficiel, en retirant le _ leading
85:   return parts.reverse().map(p => (p.startsWith('_') ? p.slice(1) : p));
