97: const NOISE_RX =
98:   /\b(remix|remaster(?:ed)?|edit|version|mix|hq|hd|official|video|audio|lyrics?|feat\.?|ft\.?|radio|single|album|club|extended|original|instrumental|acoustic|live|vol\.?\s*\d*|volume)\b/gi;
