105: /** Parse (artiste, titre) depuis un nom de fichier. Portage simplifié de
106:  *  `_artist_title()` dans app.py — suffisant pour le voisinage artiste. */
107: export function parseArtistTitle(filename: string): { artist: string | null; title: string | null } {
108:   let n = stripAccents(filename.replace(/\.[^.]+$/, '').toLowerCase());
109:   // Pattern [bracket] title
110:   const mBracket = /^\s*(?:\(\d{1,3}\))?\s*\[([^\]]+)\]\s*(.+)$/.exec(n);
111:   if (mBracket) {
112:     const a = mBracket[1].replace(NOISE_RX, ' ').trim();
113:     const t = mBracket[2].replace(NOISE_RX, ' ').trim();
114:     return { artist: a || null, title: t || null };
115:   }
116:   // Nettoyage
117:   n = n.replace(/^\s*\d{1,3}[\s._-]+/, '');
118:   n = n.replace(/\([^)]*\)/g, ' ');
119:   n = n.replace(/\[[^\]]*\]/g, ' ');
120:   n = n.replace(/_/g, ' ');
121:   // Split sur " - " ou "-" unique
122:   let segs: string[];
123:   if (n.includes(' - ')) {
124:     segs = n.split(' - ');
125:   } else if ((n.match(/-/g) || []).length === 1) {
126:     segs = n.split(/\s*-\s*/);
127:   } else {
128:     segs = [n];
129:   }
130:   segs = segs
131:     .map(s =>
132:       s
133:         .replace(/[-_.]+/g, ' ')
134:         .replace(/\s+/g, ' ')
135:         .trim(),
136:     )
137:     .filter(s => s && !/^\d{1,3}$/.test(s));
138:   if (segs.length === 0) return { artist: null, title: null };
139:   if (segs.length >= 2) {
140:     const a = segs[0].replace(/^\d{1,4}\s+/, '');
141:     return { artist: a || null, title: segs[segs.length - 1] };
142:   }
143:   const t = segs[0].replace(/^\d{1,4}\s+/, '');
144:   const mDash = /^(.{2,40}?)\s+-\s+(.+)$/.exec(t);
145:   if (mDash) return { artist: mDash[1], title: mDash[2] };
146:   return { artist: null, title: t };
147: }
