149: // ── Poids ─────────────────────────────────────────────────────────────────
150: 
151: const W_PATH = 0.5;
152: const W_ARTIST = 0.4;
153: const W_SESSION = 0.2;
154: const W_GENRE = 0.15;
155: const MAX_SCORE = W_PATH + W_ARTIST + W_SESSION + W_GENRE; // 1.25
156: const CONFIDENCE_THRESHOLD = 0.25;
157: 
158: // ── Interface ─────────────────────────────────────────────────────────────
159: 
160: export interface Suggestion {
161:   style: string;
162:   confidence: number; // 0..1
163: }
