165: // ── API ───────────────────────────────────────────────────────────────────
166: 
167: /**
168:  * Suggère un style pour un fichier épars.
169:  *
170:  * @param relPath - chemin relatif dans le dossier épars (ex. `_schranz/track.mp3`)
171:  * @param genre - tag ID3 genre (optionnel)
172:  * @param artist - artiste normalisé (issu de `artist_title()` côté backend, ou
173:  *                 null si non parsable)
174:  * @param sourceIndex - index artiste→styles (servi par `/load`)
175:  * @param sessionStyles - styles choisis en session pour des fichiers du même
176:  *                        sous-dossier épars (les plus récents d'abord)
177:  * @param tax - taxonomie des styles (dossiers source)
178:  */
179: export function suggestStyle(
180:   relPath: string,
181:   genre: string | null | undefined,
182:   artist: string | null,
183:   sourceIndex: Record<string, string[]>,
184:   sessionStyles: string[],
185:   tax: Taxonomy,
186: ): Suggestion | null {
187:   if (tax.styles.size === 0) return null;
188: 
189:   const scores = new Map<string, number>();
190: 
191:   // ── 1. Segments de chemin ─────────────────────────────────────────────
192:   const segments = pathSegments(relPath);
193:   let pathStyle: string | null = null;
194:   for (const seg of segments) {
195:     const alias = SEGMENT_ALIASES[norm(seg)];
196:     if (alias) {
197:       pathStyle = alias;
198:       break; // le plus profond gagne
199:     }
200:   }
201:   if (pathStyle && tax.styles.has(pathStyle)) {
202:     scores.set(pathStyle, (scores.get(pathStyle) ?? 0) + W_PATH);
203:   }
204: 
205:   // ── 2. Voisinage artiste ──────────────────────────────────────────────
206:   if (artist) {
207:     const artistNorm = norm(artist);
208:     const neighborStyles = sourceIndex[artistNorm];
209:     if (neighborStyles && neighborStyles.length > 0) {
210:       const counts = scoreFromStyles(neighborStyles);
211:       for (const [style, freq] of counts) {
212:         if (tax.styles.has(style)) {
213:           scores.set(style, (scores.get(style) ?? 0) + W_ARTIST * freq);
214:         }
215:       }
216:     }
217:   }
218: 
219:   // ── 3. Historique de session ───────────────────────────────────────────
220:   if (sessionStyles.length > 0) {
221:     const counts = scoreFromStyles(sessionStyles);
222:     for (const [style, freq] of counts) {
223:       if (tax.styles.has(style)) {
224:         scores.set(style, (scores.get(style) ?? 0) + W_SESSION * freq);
225:       }
226:     }
227:   }
228: 
229:   // ── 4. Genre ID3 ──────────────────────────────────────────────────────
230:   if (genre) {
231:     const genreStyle = GENRE_ALIASES[norm(genre)];
232:     if (genreStyle && tax.styles.has(genreStyle)) {
233:       scores.set(genreStyle, (scores.get(genreStyle) ?? 0) + W_GENRE);
234:     }
235:   }
236: 
237:   // ── Meilleur score ─────────────────────────────────────────────────────
238:   let bestStyle: string | null = null;
239:   let bestScore = 0;
240:   let secondScore = 0;
241:   for (const [style, score] of scores) {
242:     if (score > bestScore) {
243:       secondScore = bestScore;
244:       bestScore = score;
245:       bestStyle = style;
246:     } else if (score > secondScore) {
247:       secondScore = score;
248:     }
249:   }
250: 
251:   if (!bestStyle || bestScore === 0) return null;
252: 
253:   // Ex æquo (score1 === score2) → pas de suggestion
254:   if (bestScore === secondScore && secondScore > 0) return null;
255: 
256:   const confidence = Math.min(1, bestScore / MAX_SCORE);
257:   if (confidence < CONFIDENCE_THRESHOLD) return null;
258: 
259:   return { style: bestStyle, confidence };
260: }

