642:   // EPIC-053 : le rebuild ci-dessus efface AUSSI .focused de la colonne
643:   // source (chaque copie re-rend le panneau via sourceFiles:changed). Sans
644:   // restauration, le focus du dossier de droite DISPARAISSAIT — Tab repartait
645:   // du premier dossier et ↑↓ ne se souvenait plus de la destination : le
646:   // cycle « F5 → Tab → ↑↓ → F5 » perdait son repère. Restauration silencieuse
647:   // (preventScroll, EPIC-052) : le scroll de la colonne ne bouge pas.
648:   if (state.sourceFocusPath) {
649:     focusItemByPath(container, state.sourceFocusPath);
650:   }
651: 
652:   const { allTrees, totalCount } = buildSourceTrees(state.sourceFiles);
653: 
654:   // État vide (EPIC-014) : rien à afficher → guidance visuelle au lieu d'un panneau muet.
655:   if (allTrees.length === 0) {
656:     appendPanelEmpty(
657:       container,
658:       Object.keys(state.sourceFiles).length === 0
659:         ? 'Aucun dossier configuré — ouvre ⚙️ Config, renseigne le dossier Source puis 🔄 Scan.'
660:         : 'Aucun fichier scanné — lance 🔄 Scan.',
661:     );
662:   }
663: 
664:   const sourceFilterActive = getFilterTerm('sync-source').length > 0;
665:   if (sourceFilterActive) {
666:     const filteredCount = renderFilteredSource(container, allTrees, 'sync-source');
667:     updateFilterCount('sync-source', filteredCount, totalCount);
668:     finishSourcePanel(container, 'source-header-count', filteredCount, totalCount);
669:   } else {
670:     for (const { tree, dirPath } of allTrees) {
671:       renderDirTree(tree, container, dirPath);
672:     }
673:     renderExtraDirs(container, allTrees);
674:     finishSourcePanel(container, 'source-header-count', null, totalCount);
675:   }
676: 
677:   restore(container);
678: }

