17: /**
18:  * API fetch wrapper with retry on network errors (not on 4xx/5xx).
19:  * Returns parsed JSON response on success.
20:  */
21: export async function api<T = Record<string, unknown>>(url: string, opts: RequestOptions = {}): Promise<T> {
22:   const MAX_RETRIES = 2;
23:   let lastError: Error | null = null;
24: 
25:   for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
26:     try {
27:       const res = await fetch(url, {
28:         headers: { 'Content-Type': 'application/json' },
29:         ...opts,
30:       });
31:       if (!res.ok) {
32:         const body = (await res.json().catch(() => ({}))) as Record<string, unknown>;
33:         throw new ApiError(res.status, (body.error as string) || `HTTP ${res.status}`, body);
34:       }
35:       return res.json() as Promise<T>;
36:     } catch (err) {
37:       if (err instanceof ApiError) throw err; // pas de retry sur 4xx/5xx
38:       lastError = err instanceof Error ? err : new Error(String(err));
39:       if (attempt < MAX_RETRIES) {
40:         await new Promise(r => setTimeout(r, 500 * (attempt + 1)));
41:       }
42:     }
43:   }
44:   throw lastError || new Error('Network unreachable');
45: }

